import React, { useState, useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { LucideCopy, LucideCheck, LucideWallet, LucideArrowRight, LucideCoins, LucideRocket } from 'lucide-react';

const MINT_ADDRESS = "8yGrrj6d9p4WNPRkunVo1NwkRSX3VTo43ZS39xu7jupx";

// Helper component for copying text
const CopyButton = ({ text, label }: { text: string, label?: string }) => {
    const [copied, setCopied] = useState(false);

    const handleCopy = () => {
        navigator.clipboard.writeText(text);
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
    };

    return (
        <button 
            onClick={handleCopy}
            className="flex items-center gap-2 bg-empire-gray hover:bg-empire-red/20 border border-empire-red/30 transition-all px-4 py-2 rounded-lg group"
        >
            <span className="font-mono text-sm text-gray-300 group-hover:text-white truncate max-w-[150px] md:max-w-none">
                {label ? label : text}
            </span>
            {copied ? (
                <LucideCheck className="w-4 h-4 text-green-500" />
            ) : (
                <LucideCopy className="w-4 h-4 text-gray-400 group-hover:text-empire-red" />
            )}
        </button>
    );
};

const Navigation = () => {
    const [scrolled, setScrolled] = useState(false);

    useEffect(() => {
        const handleScroll = () => setScrolled(window.scrollY > 50);
        window.addEventListener('scroll', handleScroll);
        return () => window.removeEventListener('scroll', handleScroll);
