                        <div className="w-8 h-8 bg-empire-red rounded-full flex items-center justify-center">
                            <span className="font-orbitron font-bold text-black text-xs">D</span>
                        </div>
                        <span className="font-orbitron font-bold text-xl tracking-wider text-white">
                            DARK <span className="text-empire-red">EMPIRE</span>
                        </span>
                    </div>
                    <div className="hidden md:block">
                        <div className="ml-10 flex items-baseline space-x-8">
                            <button onClick={() => scrollTo('about')} className="text-gray-300 hover:text-white hover:bg-empire-red/10 px-3 py-2 rounded-md text-sm font-medium transition-colors">About</button>
                            <button onClick={() => scrollTo('how-to-buy')} className="text-gray-300 hover:text-white hover:bg-empire-red/10 px-3 py-2 rounded-md text-sm font-medium transition-colors">How to Buy</button>
